/// <summary>
/// Runnable class to update existing inventory locations
/// </summary>
final class METInventLocationAdhocTest
{
}

Method.Source:
    /// <summary>
    /// Class entry point. The system will call this method when a designated menu 
    /// is selected or when execution starts and this class is set as the startup class.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        METInventLocationAdhocTest instance = new METInventLocationAdhocTest();
        instance.run();
        info("@MET:Finished");

    }

    public void run()
    {
        InventLocation      inventLocation;
        METInventLocation   metInventLocation, metInventLocationLoc;

        ttsbegin;
        while select forupdate inventLocation
            notexists join metInventLocation
            where metInventLocation.InventLocation == inventLocation.RecId
        {
            metInventLocationLoc = inventLocation.metInventLocation();
            inventLocation.metPackMETInventLocation(metInventLocation);
            inventLocation.update();
        }
        ttscommit;
    }
